//############################################################################
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//   2026 ICLAB SPRING Course
//   Image Signal Process Pattern
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//############################################################################

`ifdef RTL
    `define CYCLE_TIME 4.5
`elsif GATE
    `define CYCLE_TIME 4.5
`elsif POST
    `define CYCLE_TIME 20.0
`endif

module PATTERN(
    // Output signals to DUT
    clk,
    rst_n,
    in_data_valid,
    in_data,
    cmd_valid,
    cmd,

    // Input signals from DUT
    out_valid,
    r_out,
    g_out,
    b_out
);

//================================================================
//   INPUT AND OUTPUT DECLARATION
//================================================================
output reg        clk;
output reg        rst_n;
output reg        in_data_valid;
output reg [11:0] in_data;
output reg        cmd_valid;
output reg [5:0]  cmd;

input             out_valid;
input      [7:0]  r_out;
input      [7:0]  g_out;
input      [7:0]  b_out;

//================================================================
// parameters & integer
//================================================================
real CYCLE = `CYCLE_TIME;

parameter SRAM_NUM     = 4;
parameter IMG_PER_SRAM = 16;
parameter IMG_HEIGHT   = 16;
parameter IMG_WIDTH    = 16;
parameter TOTAL_PIXELS = IMG_HEIGHT * IMG_WIDTH;
parameter SRAM_DEPTH   = IMG_PER_SRAM * TOTAL_PIXELS;
parameter CMD_NUM      = 64;
parameter GOLDEN_SIZE  = CMD_NUM * TOTAL_PIXELS;
parameter MAX_LATENCY  = 1500;

//================================================================
// file path
//================================================================
parameter INPUT_1_FILE = "../00_TESTBED/input_1.txt";
parameter INPUT_2_FILE = "../00_TESTBED/input_2.txt";
parameter INPUT_3_FILE = "../00_TESTBED/input_3.txt";
parameter INPUT_4_FILE = "../00_TESTBED/input_4.txt";

parameter OUTPUT_R_FILE = "../00_TESTBED/output_r.txt";
parameter OUTPUT_G_FILE = "../00_TESTBED/output_g.txt";
parameter OUTPUT_B_FILE = "../00_TESTBED/output_b.txt";

//================================================================
// memory
//================================================================
reg [11:0] input_sram0 [0:SRAM_DEPTH-1];
reg [11:0] input_sram1 [0:SRAM_DEPTH-1];
reg [11:0] input_sram2 [0:SRAM_DEPTH-1];
reg [11:0] input_sram3 [0:SRAM_DEPTH-1];

reg [7:0] golden_r [0:GOLDEN_SIZE-1];
reg [7:0] golden_g [0:GOLDEN_SIZE-1];
reg [7:0] golden_b [0:GOLDEN_SIZE-1];

reg [5:0] cmd_seq [0:CMD_NUM-1];

//================================================================
// variables
//================================================================
integer i;
integer cmd_idx;
integer pixel_idx;
integer golden_idx;
integer wait_cycle;
integer total_latency;
integer output_count;
integer total_errors;
integer row;
integer col;

integer diff_r;
integer diff_g;
integer diff_b;

//================================================================
// clock
//================================================================
initial begin
    clk = 0;
end

always #(CYCLE/2.0) clk = ~clk;

//================================================================
// initial
//================================================================
initial begin
    rst_n         = 1'b1;
    in_data_valid = 1'b0;
    in_data       = 'bx;
    cmd_valid     = 1'b0;
    cmd           = 'bx;

    total_latency = 0;
    total_errors  = 0;


    load_cmd_seq;
    load_test_data;

    reset_signal_task;

    #(CYCLE * 3);

    $display("========================================================================");
    $display(" Start ISP Pattern");
    $display(" Input data : input_1.txt ~ input_4.txt");
    $display(" Command num: %0d", CMD_NUM);
    $display("========================================================================");

    repeat($urandom_range(1, 4)) @(negedge clk);

    input_all_sram_task;

    for(cmd_idx = 0; cmd_idx < CMD_NUM; cmd_idx = cmd_idx + 1) begin
        repeat($urandom_range(1, 4)) @(negedge clk);
        send_cmd_and_check(cmd_idx);
    end

    YOU_PASS_task;
end

//================================================================
// basic protocol checking
//================================================================
always @(negedge clk) begin
    if(out_valid === 1'b0) begin
        if(r_out !== 8'd0 || g_out !== 8'd0 || b_out !== 8'd0) begin
            $display("---------------------------------------------------------------------------------------------");
            $display("FAIL! Output signals should be 0 when out_valid is low.");
            $display("Time: %0t, r_out=%h, g_out=%h, b_out=%h", $time, r_out, g_out, b_out);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end
    end
end

//================================================================
// task: load command sequence
//================================================================
task load_cmd_seq;
begin
    cmd_seq[00] = 6'h16;  // SRAM1 IMG06
    cmd_seq[01] = 6'h30;  // SRAM3 IMG00
    cmd_seq[02] = 6'h2a;  // SRAM2 IMG10
    cmd_seq[03] = 6'h00;  // SRAM0 IMG00
    cmd_seq[04] = 6'h06;  // SRAM0 IMG06
    cmd_seq[05] = 6'h1e;  // SRAM1 IMG14
    cmd_seq[06] = 6'h01;  // SRAM0 IMG01
    cmd_seq[07] = 6'h0e;  // SRAM0 IMG14
    cmd_seq[08] = 6'h0a;  // SRAM0 IMG10
    cmd_seq[09] = 6'h34;  // SRAM3 IMG04
    cmd_seq[10] = 6'h03;  // SRAM0 IMG03
    cmd_seq[11] = 6'h1a;  // SRAM1 IMG10
    cmd_seq[12] = 6'h15;  // SRAM1 IMG05
    cmd_seq[13] = 6'h31;  // SRAM3 IMG01
    cmd_seq[14] = 6'h27;  // SRAM2 IMG07
    cmd_seq[15] = 6'h21;  // SRAM2 IMG01
    cmd_seq[16] = 6'h26;  // SRAM2 IMG06
    cmd_seq[17] = 6'h25;  // SRAM2 IMG05
    cmd_seq[18] = 6'h1f;  // SRAM1 IMG15
    cmd_seq[19] = 6'h2c;  // SRAM2 IMG12
    cmd_seq[20] = 6'h04;  // SRAM0 IMG04
    cmd_seq[21] = 6'h1d;  // SRAM1 IMG13
    cmd_seq[22] = 6'h3e;  // SRAM3 IMG14
    cmd_seq[23] = 6'h1c;  // SRAM1 IMG12
    cmd_seq[24] = 6'h29;  // SRAM2 IMG09
    cmd_seq[25] = 6'h05;  // SRAM0 IMG05
    cmd_seq[26] = 6'h20;  // SRAM2 IMG00
    cmd_seq[27] = 6'h0f;  // SRAM0 IMG15
    cmd_seq[28] = 6'h09;  // SRAM0 IMG09
    cmd_seq[29] = 6'h2d;  // SRAM2 IMG13
    cmd_seq[30] = 6'h07;  // SRAM0 IMG07
    cmd_seq[31] = 6'h08;  // SRAM0 IMG08
    cmd_seq[32] = 6'h19;  // SRAM1 IMG09
    cmd_seq[33] = 6'h02;  // SRAM0 IMG02
    cmd_seq[34] = 6'h36;  // SRAM3 IMG06
    cmd_seq[35] = 6'h37;  // SRAM3 IMG07
    cmd_seq[36] = 6'h32;  // SRAM3 IMG02
    cmd_seq[37] = 6'h24;  // SRAM2 IMG04
    cmd_seq[38] = 6'h23;  // SRAM2 IMG03
    cmd_seq[39] = 6'h2b;  // SRAM2 IMG11
    cmd_seq[40] = 6'h33;  // SRAM3 IMG03
    cmd_seq[41] = 6'h10;  // SRAM1 IMG00
    cmd_seq[42] = 6'h3c;  // SRAM3 IMG12
    cmd_seq[43] = 6'h38;  // SRAM3 IMG08
    cmd_seq[44] = 6'h22;  // SRAM2 IMG02
    cmd_seq[45] = 6'h17;  // SRAM1 IMG07
    cmd_seq[46] = 6'h3a;  // SRAM3 IMG10
    cmd_seq[47] = 6'h3d;  // SRAM3 IMG13
    cmd_seq[48] = 6'h13;  // SRAM1 IMG03
    cmd_seq[49] = 6'h12;  // SRAM1 IMG02
    cmd_seq[50] = 6'h28;  // SRAM2 IMG08
    cmd_seq[51] = 6'h14;  // SRAM1 IMG04
    cmd_seq[52] = 6'h39;  // SRAM3 IMG09
    cmd_seq[53] = 6'h0d;  // SRAM0 IMG13
    cmd_seq[54] = 6'h2f;  // SRAM2 IMG15
    cmd_seq[55] = 6'h0b;  // SRAM0 IMG11
    cmd_seq[56] = 6'h2e;  // SRAM2 IMG14
    cmd_seq[57] = 6'h1b;  // SRAM1 IMG11
    cmd_seq[58] = 6'h3b;  // SRAM3 IMG11
    cmd_seq[59] = 6'h3f;  // SRAM3 IMG15
    cmd_seq[60] = 6'h0c;  // SRAM0 IMG12
    cmd_seq[61] = 6'h18;  // SRAM1 IMG08
    cmd_seq[62] = 6'h35;  // SRAM3 IMG05
    cmd_seq[63] = 6'h11;  // SRAM1 IMG01
end
endtask

//================================================================
// task: load test data
//================================================================
task load_test_data;
begin
    $display("  Input 1 file : %s", INPUT_1_FILE);
    $display("  Input 2 file : %s", INPUT_2_FILE);
    $display("  Input 3 file : %s", INPUT_3_FILE);
    $display("  Input 4 file : %s", INPUT_4_FILE);
    $display("  Output R file: %s", OUTPUT_R_FILE);
    $display("  Output G file: %s", OUTPUT_G_FILE);
    $display("  Output B file: %s", OUTPUT_B_FILE);

    $readmemh(INPUT_1_FILE, input_sram0);
    $readmemh(INPUT_2_FILE, input_sram1);
    $readmemh(INPUT_3_FILE, input_sram2);
    $readmemh(INPUT_4_FILE, input_sram3);

    $readmemh(OUTPUT_R_FILE, golden_r);
    $readmemh(OUTPUT_G_FILE, golden_g);
    $readmemh(OUTPUT_B_FILE, golden_b);
end
endtask

//================================================================
// task: reset
//================================================================
task reset_signal_task;
begin
    force clk = 0;
    #(CYCLE);
    rst_n = 1'b0;

    #(CYCLE * 3);
    rst_n = 1'b1;

    if(out_valid !== 1'b0 || r_out !== 8'd0 || g_out !== 8'd0 || b_out !== 8'd0) begin
        $display("---------------------------------------------------------------------------------------------");
        $display("FAIL! Output signals should be 0 after reset.");
        $display("Time: %0t, out_valid=%b, r_out=%h, g_out=%h, b_out=%h",
                 $time, out_valid, r_out, g_out, b_out);
        $display("---------------------------------------------------------------------------------------------");
        repeat(2) @(negedge clk);
        $finish;
    end

    #(CYCLE*1);
    release clk;
end
endtask

//================================================================
// task: input all SRAM data
//================================================================
task input_all_sram_task;
begin
    $display("------------------------------------------------------------------------");
    $display("  Start input 4 SRAM data, total %0d words", SRAM_NUM * SRAM_DEPTH);
    $display("------------------------------------------------------------------------");

    in_data_valid = 1'b1;

    for(i = 0; i < SRAM_DEPTH; i = i + 1) begin
        in_data = input_sram0[i];
        @(negedge clk);
    end

    for(i = 0; i < SRAM_DEPTH; i = i + 1) begin
        in_data = input_sram1[i];
        @(negedge clk);
    end

    for(i = 0; i < SRAM_DEPTH; i = i + 1) begin
        in_data = input_sram2[i];
        @(negedge clk);
    end

    for(i = 0; i < SRAM_DEPTH; i = i + 1) begin
        in_data = input_sram3[i];
        @(negedge clk);
    end

    in_data_valid = 1'b0;
    in_data       = 'bx;

    $display("  Finish input 4 SRAM data");
    $display("");
end
endtask

//================================================================
// task: send command and check output
//================================================================
task send_cmd_and_check;
    input integer id;
begin
    output_count = 0;
    wait_cycle   = 0;

    $display("------------------------------------------------------------------------");
    $display("  CMD %0d/%0d : cmd = 0x%02h, SRAM%0d IMG%0d",
             id + 1, CMD_NUM, cmd_seq[id], cmd_seq[id][5:4], cmd_seq[id][3:0]);
    $display("------------------------------------------------------------------------");

    cmd_valid = 1'b1;
    cmd       = cmd_seq[id];
    @(negedge clk);

    cmd_valid = 1'b0;
    cmd       = 'bx;

    while(out_valid !== 1'b1) begin
        wait_cycle = wait_cycle + 1;

        if(wait_cycle > MAX_LATENCY) begin
            $display("---------------------------------------------------------------------------------------------");
            $display("FAIL! Latency is over %0d cycles before out_valid rises.", MAX_LATENCY);
            $display("CMD index=%0d, cmd=0x%02h", id, cmd_seq[id]);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        @(negedge clk);
    end

    while(out_valid === 1'b1) begin
        if(output_count >= TOTAL_PIXELS) begin
            $display("---------------------------------------------------------------------------------------------");
            $display("FAIL! Output count is more than %0d pixels.", TOTAL_PIXELS);
            $display("CMD index=%0d, cmd=0x%02h", id, cmd_seq[id]);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        golden_idx = cmd_seq[id] * TOTAL_PIXELS + output_count;
        row = output_count / IMG_WIDTH;
        col = output_count % IMG_WIDTH;

        if(r_out !== golden_r[golden_idx]) begin
            diff_r = $signed({1'b0, r_out}) - $signed({1'b0, golden_r[golden_idx]});
            total_errors = total_errors + 1;

            $display("  [ERROR-R] CMD=%0d Pixel[%2d,%2d] Exp=%02h Got=%02h Diff=%0d",
                     id, row, col, golden_r[golden_idx], r_out, diff_r);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        if(g_out !== golden_g[golden_idx]) begin
            diff_g = $signed({1'b0, g_out}) - $signed({1'b0, golden_g[golden_idx]});
            total_errors = total_errors + 1;

            $display("  [ERROR-G] CMD=%0d Pixel[%2d,%2d] Exp=%02h Got=%02h Diff=%0d",
                     id, row, col, golden_g[golden_idx], g_out, diff_g);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        if(b_out !== golden_b[golden_idx]) begin
            diff_b = $signed({1'b0, b_out}) - $signed({1'b0, golden_b[golden_idx]});
            total_errors = total_errors + 1;

            $display("  [ERROR-B] CMD=%0d Pixel[%2d,%2d] Exp=%02h Got=%02h Diff=%0d",
                     id, row, col, golden_b[golden_idx], b_out, diff_b);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        output_count = output_count + 1;
        wait_cycle   = wait_cycle + 1;

        if(wait_cycle > MAX_LATENCY) begin
            $display("---------------------------------------------------------------------------------------------");
            $display("FAIL! Latency is over %0d cycles before out_valid falls.", MAX_LATENCY);
            $display("CMD index=%0d, cmd=0x%02h, received=%0d/%0d",
                     id, cmd_seq[id], output_count, TOTAL_PIXELS);
            $display("---------------------------------------------------------------------------------------------");
            repeat(2) @(negedge clk);
            $finish;
        end

        @(negedge clk);
    end

    if(output_count !== TOTAL_PIXELS) begin
        $display("---------------------------------------------------------------------------------------------");
        $display("FAIL! Output count mismatch.");
        $display("CMD index=%0d, cmd=0x%02h, expected=%0d, got=%0d",
                 id, cmd_seq[id], TOTAL_PIXELS, output_count);
        $display("---------------------------------------------------------------------------------------------");
        repeat(2) @(negedge clk);
        $finish;
    end

    total_latency = total_latency + wait_cycle;

    $display("  PASS CMD %0d: latency=%0d cycles, output=%0d pixels",
             id, wait_cycle, output_count);
    $display("");
end
endtask

